import{_ as e,c as r,o as i,aj as t,ak as p,al as s,am as l,an as n,ao as o,ap as h,aq as c,ar as _,as as m,at as d,au as g}from"./chunks/framework.DIUUAxmi.js";const O=JSON.parse('{"title":"1 尚品甄选项目介绍","description":"","frontmatter":{},"headers":[],"relativePath":"doc-menu/project/shangpin-selection/01 尚品甄选-项目概述.md","filePath":"doc-menu/project/shangpin-selection/01 尚品甄选-项目概述.md"}'),b={name:"doc-menu/project/shangpin-selection/01 尚品甄选-项目概述.md"};function u(B,a,C,f,x,k){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="_1-尚品甄选项目介绍" tabindex="-1">1 尚品甄选项目介绍 <a class="header-anchor" href="#_1-尚品甄选项目介绍" aria-label="Permalink to “1 尚品甄选项目介绍”">​</a></h1><p>尚品甄选是一个B2C模式的电子商务平台，包含后台管理系统和前台用户系统。项目采用前后端分离开发模式，基于SpringBoot + SpringCloud微服务架构，集众多主流技术于一身，是一款最适合新手入门的企业级项目。</p><p><img src="'+p+'" alt="13337676199733764"></p><h2 id="_1-1-电商基本概念" tabindex="-1">1.1 电商基本概念 <a class="header-anchor" href="#_1-1-电商基本概念" aria-label="Permalink to “1.1 电商基本概念”">​</a></h2><h3 id="_1-1-1-电商简介" tabindex="-1">1.1.1 电商简介 <a class="header-anchor" href="#_1-1-1-电商简介" aria-label="Permalink to “1.1.1 电商简介”">​</a></h3><p>电商是指利用互联网技术，将商品信息、交易、支付等业务进行电子化处理，实现线上购买和线下物流配送的商业活动。它将传统的商业活动转化为了电子商务活动，使得消费者可以足不出户地浏览、挑选商品，并通过电子支付方式完成付款，最终实现商品的快速配送。常见的电商平台：京东、天猫、亚马逊、咸鱼、淘宝...</p><h3 id="_1-1-2-电商模式" tabindex="-1">1.1.2 电商模式 <a class="header-anchor" href="#_1-1-2-电商模式" aria-label="Permalink to “1.1.2 电商模式”">​</a></h3><p>电商模式是指电子商务平台和线上商家之间进行业务合作的方式，主要包括以下几种：</p><h4 id="b2c" tabindex="-1">B2C <a class="header-anchor" href="#b2c" aria-label="Permalink to “B2C”">​</a></h4><p><strong>B2C</strong>是Business-to-Customer的缩写，而其中文简称为“<strong>商对客</strong>”。“商对客”是电子商务的一种模式，也就是通常说的直接面向消费者销售产品和服务商业零售模式。这种形式的电子商务一般以网络零售业为主，主要借助于互联网开展在线销售活动。B2C即企业通过互联网为消费者提供一个新型的购物环境——网上商店，消费者通过网络在网上购物、网上支付等消费行为。</p><p>案例：唯品会、亚马逊</p><p><img src="'+s+'" alt="image-20230826111146585"></p><h4 id="b2b" tabindex="-1">B2B <a class="header-anchor" href="#b2b" aria-label="Permalink to “B2B”">​</a></h4><p>B2B （ Business to Business）是指进行电子商务交易的供需双方都是商家（或企业、公司），她（他）们使用了互联网的技术或各种商务网络平台，完成商务交易的过程。电子商务是现代 B2B marketing的一种具体主要的表现形式。</p><p>案例：阿里巴巴1688</p><p><img src="'+l+'" alt="image-20230826093604173"></p><h4 id="b2b2c" tabindex="-1">B2B2C <a class="header-anchor" href="#b2b2c" aria-label="Permalink to “B2B2C”">​</a></h4><p>B2B2C是一种电子商务类型的网络购物商业模式，B是BUSINESS的简称，C是CUSTOMER的简称，第一个B指的是商品或服务的供应商，第二个B指的是从事电子商务的企业，C则是表示消费者。</p><p>案例：京东</p><p><img src="'+n+'" alt="image-20230826092950894"></p><h4 id="c2c" tabindex="-1">C2C <a class="header-anchor" href="#c2c" aria-label="Permalink to “C2C”">​</a></h4><p>C2C即 Customer（Consumer） to Customer（Consumer），意思就是消费者个人间的电子商务行为。比如一个消费者有一台电脑，通过网络进行交易，把它出售给另外一个消费者，此种交易类型就称为C2C电子商务。</p><p>案例：闲鱼</p><p><img src="'+o+'" alt="image-20230826093845687"></p><h4 id="o2o" tabindex="-1">O2O <a class="header-anchor" href="#o2o" aria-label="Permalink to “O2O”">​</a></h4><p>O2O即Online To Offline（在线离线/线上到线下），是指将线下的商务机会与互联网结合，让互联网成为线下交易的平台，这个概念最早来源于美国。O2O的概念非常广泛，既可涉及到线上，又可涉及到线下,可以通称为O2O。O2O这种在线支付购买线下的商品和服务，再到线下享受服务的模式也被证实可以很快被消费者接受。</p><p>案例：美团优选</p><p><img src="'+h+'" alt="image-20230826093958420"></p><h2 id="_1-2-业务功能介绍" tabindex="-1">1.2 业务功能介绍 <a class="header-anchor" href="#_1-2-业务功能介绍" aria-label="Permalink to “1.2 业务功能介绍”">​</a></h2><p><strong>后台管理系统功能</strong>：平台管理员用来维护系统相关的基础数据。包含用户登录、权限管理、商品管理、商品分类管理、商品规格管理、订单管理等</p><p>线上体验地址：<a href="http://spzx-admin.atguigu.cn/" target="_blank" rel="noreferrer">http://spzx-admin.atguigu.cn/</a></p><p><img src="'+c+'" alt="image-20230826091957239"></p><p><strong>前台用户系统功能</strong>： 包含首页数据显示，分类显示、查询商品数据、用户注册登录、购物车模块、订单模块等</p><p>线上体验地址：<a href="http://spzx.atguigu.cn/" target="_blank" rel="noreferrer">http://spzx.atguigu.cn/</a></p><p><img src="'+_+'" alt="image-20230826113125761"></p><h2 id="_1-3-系统架构介绍" tabindex="-1">1.3 系统架构介绍 <a class="header-anchor" href="#_1-3-系统架构介绍" aria-label="Permalink to “1.3 系统架构介绍”">​</a></h2><ul><li>后台管理系统后端采用的是单体架构【就是把所有的功能写在同一个项目中】，如下所示：</li></ul><p><img src="'+m+'" alt="image-20230713135826379"></p><ul><li>前台用户系统的后端采用的是微服务系统架构【一个模块就是一个独立服务】，如下图所示：</li></ul><p><img src="'+d+'" alt="image-20230713140317467"></p><ul><li><p>项目使用技术栈</p></li><li><p>后端：Spring Boot、Spring Cloud Alibaba、Redis、EasyExcel、Minio、短信平台、支付宝支付等</p></li><li><p>前端：Vue3、ES6、Node.js、NPM、Element Plus、ECharts等</p></li></ul><h2 id="_1-4-前后端分离开发" tabindex="-1">1.4 前后端分离开发 <a class="header-anchor" href="#_1-4-前后端分离开发" aria-label="Permalink to “1.4 前后端分离开发”">​</a></h2><p>尚品甄选采用的开发模式是前后端分离的开发模式。前后端分离开发是一种软件系统的设计和开发模式，将用户界面、逻辑处理和数据层从一个整体应用程序中分离出来，在前端和后端之间建立规范化接口，使得前端和后端可以独立开发、测试、部署和升级。</p><p>如下图所示：</p><p><img src="'+g+'" alt="006"></p><p>注意：</p><p>1、接口：就是一个http的请求地址，接口就规定了请求方式、请求路径、请求参数、响应结果</p><p>2、在当前的前后端分离开发中前端和后端传输的数据是json格式</p>',48)])])}const S=e(b,[["render",u]]);export{O as __pageData,S as default};
